. (Join-Path $PSScriptRoot 'experiment-1-22-artifact-contract.ps1')
$script:Exp123Required=@('run-config.json','client-results.json','client-progress.jsonl','pool/pool-metrics.jsonl','pool/pool-metrics.jsonl.summary.json','pool/collector-coverage.json','pool/collector-lifecycle.json','application/container-stop.json','application/docker-logs.stdout.log','application/docker-logs.stderr.log','application/docker-logs-capture.json','application/application.log','database/database-metrics.jsonl','container/container-stats.jsonl','mock/load-stop-mock-metrics.json','drain/mock-drain-summary.json','verification-summary.json','provenance/runtime-provenance.json','provenance/execution-timeline.json','execution-summary.json')
function Write-Exp123Json($Value,[string]$Path){New-Item -ItemType Directory -Force (Split-Path $Path)|Out-Null;$Value|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $Path -Encoding UTF8}
function Get-Exp123Json([string]$Path){Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json -ErrorAction Stop}
function Get-Exp123Time($Object,[string]$Name){$d=[DateTimeOffset]::MinValue;if(-not[DateTimeOffset]::TryParse([string]$Object.$Name,[ref]$d)){throw "Invalid timestamp: $Name"};$d.ToUniversalTime()}
function Assert-Exp123Timeline([object]$Timeline){$keys=@('collectorProcessStartedAt','collectorFirstValidSampleAt','coreInvocationStartedAt','coreInvocationCompletedAt','collectorFirstSampleCoveringCoreEndAt','postCoreCoverageConfirmedAt','collectorStopSignalIssuedAt','collectorProcessCompletedAt','applicationStopStartedAt','applicationStopCompletedAt','applicationLogCaptureStartedAt','applicationLogCaptureCompletedAt','artifactValidationCompletedAt','finalizationCompletedAt');$v=@{};foreach($k in $keys){$v[$k]=Get-Exp123Time $Timeline $k};for($i=1;$i-lt$keys.Count;$i++){if($v[$keys[$i]]-lt$v[$keys[$i-1]]){throw "Timeline order invalid: $($keys[$i-1]) -> $($keys[$i])"}};if($Timeline.collectorFirstSampleCoveringCoreEndAt -ne $Timeline.coverageFirstSampleCoveringCoreEndAt -and $null -ne $Timeline.coverageFirstSampleCoveringCoreEndAt){throw 'Timeline coverage identity mismatch'}}
function Assert-Exp123CollectorLifecycle([string]$Root){$l=Get-Exp123Json (Join-Path $Root 'pool/collector-lifecycle.json');$tl=Get-Exp123Json (Join-Path $Root 'provenance/execution-timeline.json');foreach($k in @('summaryCollectorStatus','summaryFailures','summaryStopSignalObserved')){if($null -eq $l.PSObject.Properties[$k]){throw "Lifecycle field missing: $k"}};if($l.mode-ne'CORE_BOUND_STOP_SIGNAL'-or$l.lifecycleStatus-ne'COLLECTOR_LIFECYCLE_PASSED'-or$l.failureType-ne$null-or$l.stopSignalObserved-ne$true-or$l.processExitCode-ne0-or$l.summaryCollectorStatus-ne'COLLECTOR_STOPPED_BY_SIGNAL'-or$l.summaryFailures-ne0-or$l.summaryStopSignalObserved-ne$true){throw 'Collector lifecycle contract failed'};foreach($k in @('collectorFirstSampleCoveringCoreEndAt','postCoreCoverageConfirmedAt','collectorStopSignalIssuedAt','collectorProcessCompletedAt')){if($l.$k -ne $tl.$k){throw "Lifecycle timeline identity mismatch: $k"}}}
function Assert-Exp123CollectorCoverage([string]$Root){$c=Get-Exp123Json (Join-Path $Root 'pool/collector-coverage.json');if($c.coverageStatus-ne'COLLECTOR_COVERAGE_PASSED'-or-not$c.coversCoreStart-or-not$c.coversCoreEnd-or$c.invalidSampleCount-ne0-or$c.collectorFailures-ne0){throw 'Collector coverage contract failed'};if($c.collectorFirstSampleCoveringCoreEndAt -ne $c.waitReturnedFirstCoveringSampleAt){throw 'Coverage first-covering identity failed'}}
function Assert-Exp123RuntimeProvenance([string]$Root){$p=Get-Exp123Json (Join-Path $Root 'provenance/runtime-provenance.json');$r=Get-Exp123Json (Join-Path $Root 'run-config.json');if($p.runtimeProvenance-ne'ACTUAL'-or$p.runId-ne$r.runId-or$p.condition-ne$r.condition-or$p.applicationImageId-ne$r.applicationImageId-or$p.mockImageId-ne$r.mockImageId){throw 'Runtime provenance mismatch'};if($p.composeFiles.Count-ne7){throw 'Compose provenance incomplete'};foreach($f in $p.composeFiles){if([string]::IsNullOrWhiteSpace([string]$f.path)-or[string]::IsNullOrWhiteSpace([string]$f.sha256)){throw 'Compose SHA-256 missing'}}}
function Assert-Exp123CaptureIdentity([string]$Root){$r=Get-Exp123Json (Join-Path $Root 'run-config.json');$s=Get-Exp123Json (Join-Path $Root 'application/container-stop.json');$c=Get-Exp123Json (Join-Path $Root 'application/docker-logs-capture.json');if($s.runId-ne$r.runId-or$c.runId-ne$r.runId-or$s.containerId-ne$c.containerId){throw 'Stop/capture identity mismatch'};if([int64]$c.stdoutBytes-ne([IO.FileInfo]::new($c.stdoutPath)).Length-or[int64]$c.stderrBytes-ne([IO.FileInfo]::new($c.stderrPath)).Length-or([int64]$c.stdoutBytes+[int64]$c.stderrBytes)-le0){throw 'Capture byte contract failed'}}
function Assert-Exp123BaseArtifacts([string]$Root){foreach($r in $script:Exp123Required){$p=Join-Path $Root $r;if(-not(Test-Path $p)){throw "Required artifact missing: $r"};if($r -notin @('application/docker-logs.stdout.log','application/docker-logs.stderr.log') -and([IO.FileInfo]::new($p)).Length-le0){throw "Required artifact empty: $r"}};foreach($r in @('run-config.json','pool/pool-metrics.jsonl.summary.json','pool/collector-coverage.json','pool/collector-lifecycle.json','application/container-stop.json','application/docker-logs-capture.json','provenance/runtime-provenance.json','provenance/execution-timeline.json','execution-summary.json')){$null=Get-Exp123Json (Join-Path $Root $r)};$lines=@(Get-Content (Join-Path $Root 'pool/pool-metrics.jsonl')|Where-Object{$_.Trim()});if($lines.Count-le1){throw 'Pool samples incomplete'};foreach($line in $lines){$null=$line|ConvertFrom-Json};Assert-Exp123CollectorLifecycle $Root;Assert-Exp123CollectorCoverage $Root;Assert-Exp123RuntimeProvenance $Root;Assert-Exp123CaptureIdentity $Root}
function Assert-Exp123StructuralArtifacts([string]$Root){Assert-Exp123BaseArtifacts $Root;$s=Get-Exp123Json (Join-Path $Root 'execution-summary.json');if($s.executionStatus-ne'FINALIZING'-or$s.artifactValidation-ne'PENDING'){throw 'Structural summary invalid'}}
function Assert-Exp123CommittedArtifacts([string]$Root){Assert-Exp123BaseArtifacts $Root;$s=Get-Exp123Json (Join-Path $Root 'execution-summary.json');if($s.executionStatus-ne'COMPLETED'-or$s.artifactValidation-ne'PASSED'){throw 'Committed summary invalid'};$tl=Get-Exp123Json (Join-Path $Root 'provenance/execution-timeline.json');Assert-Exp123Timeline $tl}
function Set-Exp123Terminal([string]$Root,[ValidateSet('COMPLETED','EXECUTION_FAILED')][string]$State){Remove-Item (Join-Path $Root 'RUNNING') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $Root 'COMPLETED') -Force -ErrorAction SilentlyContinue;Remove-Item (Join-Path $Root 'EXECUTION_FAILED') -Force -ErrorAction SilentlyContinue;New-Item -ItemType File (Join-Path $Root $State)|Out-Null}
